// Classifica o que a Meta (WhatsApp Cloud API) entrega. Nada é descartado em silêncio: o que
// não vai ser atendido sai com processar=false e o motivo, para aparecer na execução.
// O eco das próprias respostas é barrado depois, pelo nó "Eco?".
//
// Aceita as duas formas de entrada, para o nó de gatilho poder trocar sem quebrar isto aqui:
//   - webhook cru:      { object, entry: [ { changes: [ { field, value } ] } ] }
//   - WhatsApp Trigger: { ...value, field }   (um item por change, já achatado)
const KINDS = {
  image:    'imagem',
  video:    'video',
  audio:    'audio',
  document: 'documento',
  sticker:  'imagem',
};

const out = [];
const mudancas = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  if (Array.isArray(body.entry)) {
    if (body.object && body.object !== 'whatsapp_business_account') {
      out.push({ json: { processar: false, motivo: `objeto "${body.object}": só atendo whatsapp_business_account` } });
      continue;
    }
    for (const entry of body.entry) {
      for (const change of entry.changes ?? []) {
        mudancas.push({ field: change.field ?? '', value: change.value ?? {} });
      }
    }
  } else if (body.metadata || body.messages || body.statuses || body.errors) {
    const { field, ...value } = body;
    mudancas.push({ field: field ?? 'messages', value });
  } else {
    out.push({ json: { processar: false, motivo: `payload irreconhecível (${Object.keys(body).join(', ') || 'vazio'})` } });
  }
}

for (const { field, value } of mudancas) {
  const phone_number_id = value.metadata?.phone_number_id ?? '';

  const ignorar = (motivo, extra = {}) => out.push({ json: {
    processar: false, motivo, field, phone_number_id, ...extra,
  }});

  if (field !== 'messages') {
    ignorar(`campo "${field}": só atendo messages`); continue;
  }
  // Confirmações de entrega/leitura do que NÓS enviamos chegam no mesmo webhook.
  if (value.statuses?.length) {
    const s = value.statuses[0];
    ignorar(`status "${s.status}" da mensagem ${s.id ?? ''}`); continue;
  }
  if (value.errors?.length) {
    const e = value.errors[0];
    ignorar(`erro da Meta ${e.code ?? ''}: ${e.title ?? ''}`); continue;
  }

  const messages = value.messages ?? [];
  if (messages.length === 0) {
    ignorar(`mudança sem mensagens (${Object.keys(value).join(', ')})`); continue;
  }

  for (const msg of messages) {
    const wa_id = msg.from ?? value.contacts?.[0]?.wa_id ?? '';
    const push_name = value.contacts?.[0]?.profile?.name ?? '';
    const comum = { wa_id, push_name, message_id: msg.id ?? '' };

    let kind = null, text = '', caption = '', mimetype = '', media_id = '';

    if (msg.type === 'text') {
      kind = 'texto';
      text = (msg.text?.body ?? '').trim();
    } else if (KINDS[msg.type]) {
      kind = KINDS[msg.type];
      const media = msg[msg.type] ?? {};
      media_id = media.id ?? '';
      mimetype = media.mime_type ?? '';
      caption = (media.caption ?? '').trim();
      text = caption;
      if (!media_id) {
        ignorar(`mídia ${msg.type} sem id para baixar`, comum); continue;
      }
    } else {
      ignorar(`tipo de mensagem não suportado (${msg.type ?? 'vazia'})`, comum); continue;
    }

    let d = (wa_id || '').replace(/\D/g, '');
    if (!d) {
      ignorar('mensagem sem remetente', comum); continue;
    }

    // Celular BR sem o 9º dígito: +55 + DDD + 8 dígitos começando em 6-9.
    // A API do Condo Manager casa por igualdade exata, sem isso vira falso "não cadastrado".
    // Só o `phone` ganha o 9; para responder vale o wa_id exatamente como a Meta mandou.
    if (d.startsWith('55') && d.length === 12 && /^[6-9]/.test(d.slice(4))) {
      d = '55' + d.slice(2, 4) + '9' + d.slice(4);
    }

    out.push({ json: {
      processar: true,
      phone: '+' + d,
      wa_id,                    // devolve exatamente para quem escreveu
      kind,                     // texto | imagem | audio | video | documento
      text,
      caption,
      mimetype,
      media_id,                 // vazio quando é texto
      message_id: msg.id ?? '',
      phone_number_id,          // de qual número nosso a mensagem chegou
      push_name,
      timestamp: msg.timestamp ?? '',
    }});
  }
}

return out;

// O download da Meta traz só os bytes: sem nome e, às vezes, sem mime confiável.
// A transcrição do OpenAI e o upload para o Condo Manager dependem da extensão.
const EXT = {
  'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac',
  'audio/amr': 'amr', 'audio/wav': 'wav', 'audio/webm': 'webm',
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',
  'video/mp4': 'mp4', 'video/3gpp': '3gp',
  'application/pdf': 'pdf',
};

const m = $('Mensagem').item.json;
const items = $input.all();

for (const item of items) {
  const bin = item.binary?.data;
  if (!bin) continue;

  const mime = ((m.mimetype || bin.mimeType || '').split(';')[0] || '').trim();
  const ext = EXT[mime] ?? (mime.split('/')[1] || 'bin');

  bin.mimeType = mime || bin.mimeType;
  bin.fileExtension = ext;
  bin.fileName = `${m.media_id || m.message_id}.${ext}`;
}

return items;

